    print('saved',p,'remaining',o.meta['time_left_s'],'q',np.array(o.meta['proprio']['now'])[4:11], 'eef', np.array(o.meta['proprio']['now'])[26:29],flush=True)
    return o

def load_meta(): return json.loads((OUT/'latest.json').read_text())
def prop(m): return np.asarray(m['proprio']['now'])
def cmd(m):
    p=prop(m);return p[29:42].copy()
def pixel(cam,u,v,path=None):
    m=load_meta() if path is None else json.loads((path/'meta.json').read_text())
    dep=np.load(OUT/'latest.npz')[cam+'_depth'] if path is None else np.load(path/f'depth_{cam}.npy')
    if dep.ndim==3:dep=dep[-1]
    z=float(dep[int(v),int(u)]); K=np.array(m['cameras'][cam]['intrinsic_cv']);T=np.array(m['cameras'][cam]['cam2world_gl'])
    pc=np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1])
    return (T@pc)[:3],z

def obs(r,label='observe'):return save(r.get_obs(include_depth=True,video='none'),label)
def submit(r,A,label):
    return save(r.submit('joint_position',np.asarray(A),cameras=[CAM,EYE],include_depth=True,video='none',note=label),label)
def joint(r,q,seconds=1.5,grip=None,label='joint'):
    m=load_meta();c=cmd(m);start=prop(m)[4:11]; N=max(2,round(seconds/.05)); A=np.tile(c,(N,1));A[:,8:12]=0;A[:,12]=-1
    A[:,:7]=np.linspace(start,q,N)
    if grip is not None:A[:,7]=grip
    return submit(r,A,label)

def fit():
    ms=[json.loads(p.read_text()) for p in sorted(ROOT.glob('*cal*/meta.json'))]
    ms=[json.loads((ROOT/'initial/meta.json').read_text())]+ms
    Q=np.array([prop(m)[4:11] for m in ms]); P=np.array([prop(m)[26:29] for m in ms]);C=np.array([np.array(m['cameras'][EYE]['cam2world_gl'])[:3,:3] for m in ms])
    def residual(x):
        R=Rotation.from_rotvec(x[:3]).as_matrix();off=x[3:6];tip=x[6:9];RC=Rotation.from_rotvec(x[9:12]).as_matrix()
        out=[]
        for q,p,c in zip(Q,P,C):
            f=fk(q);out.extend((R@(f[:3,3]+f[:3,:3]@tip)+off-p)*10)
            out.extend(Rotation.from_matrix((R@f[:3,:3]@RC).T@c).as_rotvec())
        return out
    x=np.zeros(12);x[2]=np.pi/2;x[3:6]=[1.15,-1.15,.9];x[8]=.1
    ls=least_squares(residual,x,max_nfev=2000)
    np.save(OUT/'kin.npy',ls.x);print('fit',ls.cost,ls.x,'max',max(abs(np.array(residual(ls.x)))))

def pose(q):
    x=np.load(OUT/'kin.npy');R=Rotation.from_rotvec(x[:3]).as_matrix();f=fk(q)
    p=R@(f[:3,3]+f[:3,:3]@x[6:9])+x[3:6];C=R@f[:3,:3]@Rotation.from_rotvec(x[9:12]).as_matrix()
    # Account for mobile base motion using the measured current pose and orientation.
    m=load_meta();qm=prop(m)[4:11];fm=fk(qm)
    pm=R@(fm[:3,3]+fm[:3,:3]@x[6:9])+x[3:6];Cm=R@fm[:3,:3]@Rotation.from_rotvec(x[9:12]).as_matrix()
    actual=np.array(m['cameras'][EYE]['cam2world_gl'])[:3,:3];delta=actual@Cm.T
    return prop(m)[26:29]+delta@(p-pm),delta@C

def move(r,target,rot=None,seconds=2,label='move',grip=None):
    m=load_meta();q0=prop(m)[4:11];target=np.asarray(target)
    if rot is None: rot=np.array(m['cameras'][EYE]['cam2world_gl'])[:3,:3]
    def fun(q):
        p,C=pose(q);return np.r_[(p-target)*6,Rotation.from_matrix(rot.T@C).as_rotvec(),.025*(q-q0)]
    limits=([-2.8973,-1.7628,-2.8973,-3.0718,-2.8973,-.0175,-2.8973],[2.8973,1.7628,2.8973,-.0698,2.8973,3.7525,2.8973])
    ls=least_squares(fun,np.clip(q0,np.array(limits[0])+1e-5,np.array(limits[1])-1e-5),bounds=limits,max_nfev=300)
    p,C=pose(ls.x);print('IK',p,'err',p-target,'rot',Rotation.from_matrix(rot.T@C).as_rotvec(),flush=True)
    if np.linalg.norm(p-target)>.03:raise RuntimeError('unreachable target')
    return joint(r,ls.x,seconds,grip,label)

def cart(r,target,rot=None,step=.035,label='cart',grip=None):
    p0=prop(load_meta())[26:29];C0=np.array(load_meta()['cameras'][EYE]['cam2world_gl'])[:3,:3]
    if rot is None:rot=C0
    rv=Rotation.from_matrix(C0.T@rot).as_rotvec()
    N=max(1,int(np.ceil(max(np.linalg.norm(np.asarray(target)-p0)/step,np.linalg.norm(rv)/.15))))
    for i in range(1,N+1):
        p=p0+(np.asarray(target)-p0)*i/N;C=C0@Rotation.from_rotvec(rv*i/N).as_matrix()
        move(r,p,C,.7,label+str(i),grip)
        err=np.linalg.norm(prop(load_meta())[26:29]-p)
        if err>.035:
            print('STOP tracking error',err,flush=True);return False
    return True

if __name__=='__main__':
    r=Robot();op=sys.argv[1]
    if op=='obs':obs(r)
    elif op=='pixel':
        cam={'c':CAM,'l':'robot0_agentview_left','r':'robot0_agentview_right','e':EYE}[sys.argv[2]]
        for uv in sys.argv[3:]:u,v=map(float,uv.split(','));print(uv,pixel(cam,u,v))
    elif op=='cal':
        if not (OUT/'latest.json').exists():obs(r,'cal_start')
        q0=prop(load_meta())[4:11]
        for i in range(7):
            q=q0.copy();q[i]+=.09
            joint(r,q,1.2,label=f'cal{i}')
            joint(r,q0,1.2,label=f'calreturn{i}')
        fit()
    elif op=='fit':fit()
    elif op=='move':move(r,list(map(float,sys.argv[2:5])),seconds=float(sys.argv[5]) if len(sys.argv)>5 else 2)
    elif op=='joint':joint(r,list(map(float,sys.argv[2:9])),seconds=float(sys.argv[9]) if len(sys.argv)>9 else 2)
    elif op=='grip':joint(r,prop(load_meta())[4:11],1.0,grip=float(sys.argv[2]),label='grip')
    elif op=='base':
